import { describe, expect, it } from "vitest";

import { discontinuedCourse, makeFetcher, referencingClass } from "../src/fixtures";
import { reconcileCourses } from "../src/reconcile";
import { StoredCourseRow } from "../src/types";

function findRow(
  rows: StoredCourseRow[],
  courseId: string,
  subject: string,
  number: string
): StoredCourseRow | undefined {
  return rows.find(
    (r) => r.courseId === courseId && r.subject === subject && r.number === number
  );
}

describe("reconcileCourses", () => {
  it("normal reconciliation: upserts changed rows and never touches an unrelated, discontinued-but-referenced course", async () => {
    const stored: StoredCourseRow[] = [
      {
        courseId: "24401",
        subject: "COMPSCI",
        number: "61A",
        title: "Structure and Interpretation of Computer Programs",
      },
      discontinuedCourse,
    ];

    const fetchCourses = makeFetcher([
      {
        courseId: "24401",
        subject: "COMPSCI",
        number: "61A",
        title: "Structure and Interpretation of Computer Programs, 2nd Ed.",
      },
    ]);

    const result = await reconcileCourses({ stored, fetchCourses });

    expect(result.deletedCount).toBe(0);
    expect(result.upsertedCount).toBe(1);

    const updated = findRow(result.stored, "24401", "COMPSCI", "61A");
    expect(updated?.title).toBe(
      "Structure and Interpretation of Computer Programs, 2nd Ed."
    );

    // The discontinued course is absent from every fetch by design -- that
    // must never be read as "delete it".
    expect(
      findRow(
        result.stored,
        discontinuedCourse.courseId,
        discontinuedCourse.subject,
        discontinuedCourse.number
      )
    ).toBeDefined();
  });

  it("renumbering: deletes only the superseded (courseId, subject, number) row, keeps the courseId alive via its new number", async () => {
    const stored: StoredCourseRow[] = [
      // Stale row left over from before the renumbering landed.
      { courseId: "24777", subject: "COLWRIT", number: "6A", title: "Reading and Composition" },
      // The new number, already synced by a previous run.
      { courseId: "24777", subject: "COLWRIT", number: "22B", title: "Reading and Composition" },
      discontinuedCourse,
    ];

    // This run, SIS only reports the course under its new number.
    const fetchCourses = makeFetcher([
      { courseId: "24777", subject: "COLWRIT", number: "22B", title: "Reading and Composition" },
    ]);

    const result = await reconcileCourses({ stored, fetchCourses });

    // The old number is gone...
    expect(findRow(result.stored, "24777", "COLWRIT", "6A")).toBeUndefined();
    // ...but the courseId is still represented by its current number.
    expect(findRow(result.stored, "24777", "COLWRIT", "22B")).toBeDefined();
    expect(result.deletedCount).toBe(1);

    // Still must not touch the unrelated discontinued course.
    expect(
      findRow(
        result.stored,
        discontinuedCourse.courseId,
        discontinuedCourse.subject,
        discontinuedCourse.number
      )
    ).toBeDefined();
  });

  it("discontinued-but-referenced course: absent from every fetch, must survive because a past-term class still joins against it", async () => {
    const stored: StoredCourseRow[] = [
      { courseId: "88200", subject: "EALANG", number: "121", title: "East Asian Languages" },
      discontinuedCourse,
    ];
    const classes = [referencingClass];

    const fetchCourses = makeFetcher([
      { courseId: "88200", subject: "EALANG", number: "121", title: "East Asian Languages" },
    ]);

    const result = await reconcileCourses({ stored, fetchCourses });

    expect(result.deletedCount).toBe(0);

    const survivor = findRow(
      result.stored,
      discontinuedCourse.courseId,
      discontinuedCourse.subject,
      discontinuedCourse.number
    );
    expect(survivor).toBeDefined();

    // Sanity: the class that depends on this course can still resolve it.
    const classCourseIds = new Set(result.stored.map((r) => r.courseId));
    expect(classes.every((c) => classCourseIds.has(c.courseId))).toBe(true);
  });

  it("partial fetch: refuses to reconcile when pages failed, rather than writing from a truncated snapshot", async () => {
    const stored: StoredCourseRow[] = [
      {
        courseId: "24401",
        subject: "COMPSCI",
        number: "61A",
        title: "Structure and Interpretation of Computer Programs",
      },
      discontinuedCourse,
    ];

    // Simulates SIS pagination where courseId rows straddle a page boundary
    // and one of those pages failed after retries.
    const fetchCourses = makeFetcher(
      [
        {
          courseId: "24401",
          subject: "COMPSCI",
          number: "61A",
          title: "Structure and Interpretation of Computer Programs",
        },
      ],
      [1900, 1901]
    );

    await expect(reconcileCourses({ stored, fetchCourses })).rejects.toThrow();
  });
});
